using System.Numerics;
using System.Text.Json;
namespace BobbyBoi;
static class WorldTests {
 public static void Run(){Directory.CreateDirectory("artifacts");WorldEventDirector.Test();var rng=new Random(23);var catches=Enumerable.Range(0,10000).Select(_=>WorldLoot.Catch(rng).Name).ToArray();if(catches.Distinct().Count()<25||catches.Count(x=>x=="Raw Cod")<=catches.Count(x=>x=="Diamond"))throw new Exception("Fishing rarity distribution");foreach(var loot in WorldLoot.Fishing)if(WorldAssets.Item(loot.Name).Faces.Count<6)throw new Exception("Missing catch model");
  var state=new WorldState{HasHouse=true,HouseBlocks=50,WolfAdopted=true,WolfName="Test wolf"};state.Achievements.Add("architect");state.Counters["fish"]=20;var round=JsonSerializer.Deserialize<WorldState>(JsonSerializer.Serialize(state))!;if(!round.HasHouse||round.WolfName!="Test wolf"||!round.Achievements.Contains("architect")||round.Counters["fish"]!=20)throw new Exception("World save roundtrip");
  var p1=new CharacterPose();var p2=new CharacterPose();using(var image=new Bitmap(200,240))using(var g=Graphics.FromImage(image)){Character.Draw(g,new(100,220),4,Act.Dance,1,.3f,0,animationPose:p1);Character.Draw(g,new(100,220),4,Act.Sleep,1,-.3f,0,animationPose:p2);}if(ReferenceEquals(p1.Previous,p2.Previous)||p1.Previous![0]==p2.Previous![0])throw new Exception("Clones share animation state");
  using(var sheet=new Bitmap(1200,650)){using var g=Graphics.FromImage(sheet);g.Clear(Color.FromArgb(23,28,24));var house=WorldAssets.House(0);house.Mesh.Draw(g,new(180,270),3,.4f);WorldAssets.Chest.Draw(g,new(440,260),5,.4f);WorldAssets.Chest.Draw(g,new(630,260),5,.4f,(v,part)=>{if(part=="lid"){v-=new Vector3(0,10,-6);float a=-1.2f;v=new(v.X,v.Y*MathF.Cos(a)-v.Z*MathF.Sin(a),v.Y*MathF.Sin(a)+v.Z*MathF.Cos(a));v+=new Vector3(0,10,-6);}return v;});WorldAssets.Wolf.Draw(g,new(900,250),5,.6f);WorldAssets.Dragon.Draw(g,new(350,490),4,.4f,(v,part)=>part.Contains("wing")?new(v.X,v.Y+Math.Abs(v.X)*.2f,v.Z):v);WorldAssets.Item("Raw Salmon").Draw(g,new(750,480),12,.4f);WorldAssets.Item("Old Boot").Draw(g,new(980,490),12,.3f);sheet.Save("artifacts/world-assets.png");}
  if(CursorPrank.Move(Cursor.Position,false))throw new Exception("Disabled cursor movement occurred");
  using var pet=new Pet(true,true);pet.VerifyWorldActivities();
 }
}
sealed partial class Pet {
 public void VerifyWorldActivities(){worldTesting=true;data.World=new(){Automatic=false};data.NaturalMobs=false;data.Volume=0;data.Expeditions.Enabled=false;mobs.Clear();data.Items=SaveData.Names.ToDictionary(n=>n,_=>0);energy=90;hunger=80;curiosity=90;mischief=80;health=20;action=Act.Idle;var report=new List<string>();
  void Start(WorldEventKind kind){if(world.Busy)CancelWorld();respawnTime=0;throwVx=vy=0;health=20;action=Act.Idle;world.Queue(kind);UpdateWorld(.1f);if(world.Active?.Spec.Kind!=kind)throw new Exception("Event did not start: "+kind);}
  void Finish(float seconds=35){for(int i=0;i<seconds*10&&world.Busy;i++)UpdateWorld(.1f);if(world.Busy)throw new Exception("Event did not finish: "+world.Active!.Spec.Kind);}
  void Snapshot(string name){var visuals=WorldVisuals().ToList();if(visuals.Count==0)return;var rect=visuals.Select(v=>v.Bounds).Aggregate(Rectangle.Union);rect=Rectangle.Intersect(rect,new Rectangle(-3000,-2000,7000,5000));if(rect.Width<1||rect.Height<1)return;using var image=WorldCanvas.Snapshot(visuals,rect);image.Save("artifacts/world-"+name+".png");}
  try{
   Start(WorldEventKind.Fishing);for(int i=0;i<35;i++)UpdateWorld(.1f);Snapshot("fishing");Finish();if(!data.World.Counters.TryGetValue("fish",out int caught)||caught!=1||data.Items.Values.Sum()<1)throw new Exception("Fishing reward missing");report.Add("PASS: fishing cast/wait/reel completes, weighted catch enters inventory.");
   Start(WorldEventKind.BuildHouse);for(int i=0;i<55;i++)UpdateWorld(.1f);int partial=data.World.HouseBlocks;if(partial<=0||partial>=HouseAsset().Cutoffs.Length)throw new Exception("House did not build sequentially");Snapshot("building");Finish();if(!data.World.HasHouse||data.World.HouseBlocks!=HouseAsset().Cutoffs.Length||!data.World.Achievements.Contains("architect"))throw new Exception("House completion missing");Snapshot("house");report.Add("PASS: house places blocks progressively, persists its state, and awards achievement.");
   Start(WorldEventKind.HouseVisit);Finish();if(actorInside)throw new Exception("House visit left character invisible");report.Add("PASS: house entry, sleep and exit recover visibility.");
   Start(WorldEventKind.Treasure);treasure!.Nested=true;treasure.Items=new(){{"Dirt",1}};int dirt=data.Items["Dirt"];Finish();if(!treasure.Claimed||data.Items["Dirt"]!=dirt+1)throw new Exception("Chest reward missing or duplicated");for(int i=0;i<10;i++)UpdateWorld(.1f);if(data.Items["Dirt"]!=dirt+1)throw new Exception("Repeated chest grant");Snapshot("chest");report.Add("PASS: nested chest opens, rewards exactly once and remains inspectable.");
   Start(WorldEventKind.AdoptWolf);Finish();if(wolf==null||!data.World.WolfAdopted||!data.World.Achievements.Contains("wolf"))throw new Exception("Wolf adoption failed");SetWolfMode("Sit");UpdateCompanions(.1f);if(wolf.Action!=Act.Sit)throw new Exception("Wolf sit command failed");SetWolfMode("Sleep");for(int n=0;n<100&&wolf.Action!=Act.Sleep;n++)UpdateCompanions(.1f);if(wolf.Action!=Act.Sleep)throw new Exception("Wolf sleep command failed");SetWolfMode("Follow");Snapshot("wolf");report.Add("PASS: wolf adoption, following, sit/sleep commands and persistent state.");
   string inventory=JsonSerializer.Serialize(data.Items);Start(WorldEventKind.Clone);Finish();if(clones.Count!=2||clones[0].Id==clones[1].Id)throw new Exception("Clone identity/cap");Snapshot("clones");WorldPassive(50);if(clones.Count!=0||JsonSerializer.Serialize(data.Items)!=inventory)throw new Exception("Clone cleanup / inventory isolation");report.Add("PASS: independent clone IDs/poses, two-clone cap, expiry, no inventory copies.");
   Start(WorldEventKind.Dragon);dragonHealth=0;UpdateWorld(.1f);Snapshot("dragon");Finish();if(!data.World.Achievements.Contains("dragon"))throw new Exception("Dragon win failed");report.Add("PASS: dragon victory, trophy reward, boss cleanup.");
   Start(WorldEventKind.Dragon);health=2;invulnerable=0;var saved=JsonSerializer.Serialize(data.Items);ApplyMobDamage(new(x+Width/2,y+Height),4,150);if(respawnTime<=0||world.Busy||JsonSerializer.Serialize(data.Items)!=saved)throw new Exception("Boss loss recovery");respawnTime=0;health=20;report.Add("PASS: boss defeat cancels activity, starts four-second respawn, preserves inventory.");
   data.World.AllowCursor=false;var cursorBefore=Cursor.Position;RequestWorld(WorldEventKind.CursorPrank);UpdateWorld(.1f);if(world.Active?.Spec.Kind==WorldEventKind.CursorPrank||Cursor.Position!=cursorBefore)throw new Exception("Cursor opt-out failed");report.Add("PASS: real cursor disabled by default and untouched in tests. Enabled movement requires manual opt-in testing.");
   standingPlatform=null;vy=250;action=Act.Fall;y=Screen.PrimaryScreen!.WorkingArea.Bottom-Height;float floor=y;if(!ThrowPhysics.SettleAtFloor(ref y,ref vy,floor)||vy!=0)throw new Exception("Floor landing regression");report.Add("PASS: floor-level falling release transitions to landing.");
   File.WriteAllLines("artifacts/world-tests.txt",report);
  }finally{timer.Stop();tray.Dispose();menu.Dispose();mobs.Dispose();worldCanvas.Dispose();objectMenu?.Dispose();}
 }
}
